#!/usr/bin/env python3
"""Embed compiled openfg SPIR-V modules into a C++ source file.

Usage: embed_openfg_shaders.py <output.cpp> <shader.spv>...
"""

import pathlib
import sys


def main():
    if len(sys.argv) < 3:
        raise SystemExit(__doc__)
    out = pathlib.Path(sys.argv[1])
    shaders = [pathlib.Path(p) for p in sys.argv[2:]]

    lines = [
        "// Generated by tools/embed_openfg_shaders.py. Do not edit.",
        '#include "openfg_shaders.hpp"',
        "",
        "#include <array>",
        "#include <cstdint>",
        "#include <string_view>",
        "",
        "namespace openfg {",
        "namespace {",
    ]

    entries = []
    for index, path in enumerate(sorted(shaders, key=lambda p: p.stem)):
        words = path.read_bytes()
        if len(words) % 4 != 0:
            raise SystemExit(f"{path}: not valid SPIR-V")
        values = [int.from_bytes(words[i:i + 4], "little") for i in range(0, len(words), 4)]
        name = path.stem
        lines.append(f"constexpr std::array<uint32_t, {len(values)}> SHADER_{index}_DATA{{{{")
        for i in range(0, len(values), 8):
            lines.append("    " + ", ".join(f"0x{v:08x}u" for v in values[i:i + 8]) + ",")
        lines.append("}};")
        entries.append((name, index, len(values)))
        lines.append("")

    lines.append("constexpr std::array<EmbeddedShader, %d> SHADERS{{" % len(entries))
    for name, index, count in entries:
        lines.append(f'    {{ "{name}", SHADER_{index}_DATA.data(), {count} }},')
    lines.append("}};")
    lines.append("} // namespace")
    lines.append("")
    lines.append("std::span<const uint32_t> embeddedShader(std::string_view name) {")
    lines.append("    for (const auto& shader : SHADERS) {")
    lines.append("        if (shader.name == name)")
    lines.append("            return { shader.data, shader.size };")
    lines.append("    }")
    lines.append("    return {};")
    lines.append("}")
    lines.append("")
    lines.append("} // namespace openfg")
    lines.append("")

    out.write_text("\n".join(lines))


if __name__ == "__main__":
    main()
